/**
 * POST /api/testimonials/verify-unified-otp
 * Member verifies the unified OTP generated by submit-all-edits.
 * One OTP marks both photo and video statuses as verified (where pending).
 */
import { applyCors, methodNotAllowed, runService } from '../../../shared/lib/handler.js';
import { verifyUnifiedOtp } from '../../../features/testimonials/testimonials.service.js';
import logger from '../../../shared/lib/logger.js';

export default async function handler(req, res) {
  if (applyCors(req, res, 'POST, OPTIONS')) return;
  if (req.method !== 'POST') return methodNotAllowed(res);

  logger.info('[testimonials/verify-unified-otp] incoming request', {
    userId: req.body?.userId ?? 'unknown',
  });

  return runService(res, () => verifyUnifiedOtp(req.body));
}
